/**
 * GENERATED by the tower baker — pre-rendered 3D tower sprites per tower
 * type, skin ("base" = no skin) and visual stage (1..6). `anchors` are
 * fractions of the image (x right, y down): `base` is the ground point under
 * the tower's centre, the rest mark live-effect points (orb, rune orbit...).
 * Every sprite covers TOWER_SPRITE_WORLD_SIZE world units. See towerSprites.ts.
 */
export interface TowerSpriteEntry {
  file: string;
  anchors: Record<string, readonly [number, number]>;
  /** Rotating part (e.g. Ironwood's ballista) baked as a horizontal strip of `frames` headings; frame k points at heading k/frames * 2pi (0 = screen-right, clockwise). Same framing as `file`. */
  turret?: { file: string; frames: number; anchors: Record<string, readonly [number, number]>[] };
}

export const TOWER_SPRITE_WORLD_SIZE = 72;

